import http.server as h, functools as f
class H(h.SimpleHTTPRequestHandler):
    def end_headers(self):
        self.send_header('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0')
        super().end_headers()
    def guess_type(self, path):
        return 'text/javascript' if path.endswith(('.js', '.mjs')) else super().guess_type(path)
h.ThreadingHTTPServer(('', 8030), f.partial(H, directory=r'C:\Users\luizn\Documents\07-PROJETOS\extTotalPlanner')).serve_forever()
